def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_HP = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    num_slots = int(day_context['supply'] // WATER_REQ)

    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])

    sorted_yesterday_bids = sorted(yesterday_bids, reverse=True)

    current_bid = DAILY_SALARY * 0.8

    if my_status['hp'] <= 2:
        current_bid = DAILY_SALARY * 1.6
    elif my_status['hp'] <= 4:
        current_bid = DAILY_SALARY * 1.2
    elif my_status['hp'] >= 8:
        current_bid = DAILY_SALARY * 0.6

    if my_status['no_water_days'] > 0:
        current_bid = max(current_bid, DAILY_SALARY * (1 + my_status['no_water_days'] * 0.2))

    if sorted_yesterday_bids:
        if num_alive_opponents >= num_slots:
            threshold_index = min(num_slots - 1, len(sorted_yesterday_bids) - 1)

            if threshold_index >= 0:
                threshold_bid = sorted_yesterday_bids[int(threshold_index)]

                if my_status['hp'] <= 4:
                    current_bid = max(current_bid, threshold_bid + 2.0)
                elif my_status['hp'] > 4:
                    current_bid = max(current_bid, threshold_bid + 0.5)
        else:
            current_bid = max(current_bid, sorted_yesterday_bids[0] * 0.9)

    final_bid = min(my_status['budget'], current_bid)

    if my_status['budget'] > 0 and final_bid < 1.0:
        final_bid = 1.0
    elif my_status['budget'] == 0:
        final_bid = 0.0

    return round(final_bid, 2)
